mapper.sql:
select TABLE_ID tableId, TABLE_NAME tableName, REMARK remark, UPDATE_TIME updateTime, HIS_NO hisNo, disCbxCol from( select bt.TABLE_ID, bt.TABLE_NAME, bt.REMARK, bt.UPDATE_TIME, '0' HIS_NO, '0' disCbxCol from BOK_TABLELIST bt where bt.STATUS = 'E'
and bt.TABLE_NAME like concat_ws('','%',#{tableName},'%')
) de
